WITH cleaned AS (SELECT id, account_id, txn_type, txn_time, merchant, is_flagged, CAST(txn_time AS DATE) txn_time_day FROM transactions WHERE txn_time >= TO_TIMESTAMP('2023-07-01 01:00:00') AND account_id IN (7, 21, 31, 39)), ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY merchant ORDER BY txn_time_day NULLS LAST, id) AS row_num FROM cleaned QUALIFY row_num = 1), deduped AS (SELECT id, txn_type, txn_time, txn_time_day, row_num FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY merchant, txn_type ORDER BY txn_time_day DESC, id) AS row_num_2 FROM ranked) ranked WHERE row_num_2 = 1), enriched AS (SELECT id, txn_type, row_num, ROW_NUMBER() OVER (PARTITION BY txn_type ORDER BY txn_time, id) row_seq, ROW_NUMBER() OVER (ORDER BY txn_time DESC, id) event_seq, ROW_NUMBER() OVER (PARTITION BY txn_type ORDER BY row_num DESC, id) event_seq_2 FROM deduped), cleaned_transactions AS (SELECT *, event_seq_2 + row_num event_seq_2_plus_row_num, GREATEST(row_num, event_seq) greatest_row_num_event_seq FROM enriched WHERE txn_type NOT IN ('FEE', 'DEBIT')), cleaned_transactions_2 AS (SELECT *, ROUND(row_num, 2) row_num_rounded FROM cleaned_transactions WHERE row_num >= 1), base AS (SELECT id, row_num, event_seq_2_plus_row_num, row_num_rounded, CAST(event_seq_2 AS DOUBLE) event_seq_2_str, CAST(event_seq_2_plus_row_num AS INT) event_seq_2_plus_row_num_int FROM cleaned_transactions_2 WHERE row_seq BETWEEN 6 AND 8) SELECT id, row_num, row_num_rounded, event_seq_2_str, event_seq_2_plus_row_num_int FROM base ORDER BY row_num_rounded DESC;
